TLM.f("Sancti/07-29",{"officium":"Commune Virginum tantum: Dilexisti","rule":["vide C6;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","sections":{"Introitus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Exáudi nos, Deus, salutáris noster: ut, sicut de beátæ Marthæ Vírginis tuæ festivitáte gaudémus; ita piæ devotiónis erudiámur afféctu."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 10:17-18; 11:1-2"},{"k":"text","la":"Fratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo."}],"Graduale":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13; 44:10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Afferéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:38-42"},{"k":"text","la":"In illo témpore: Intravit Jesus in quoddam castellum: et mulier quaedam, Martha nomine, excepit illum in domum suam et huic erat soror nomine Maria quae etiam sedens secus pedes Domini audiebat verbum illius. Martha autem satagebat circa frequens ministerium quae stetit, et ait: Domine non est tibi curae quod soror mea reliquit me solam ministrare dic ergo illi ut me adiuvet et respondens dixit illi Dominus: “Martha, Martha, sollicita es, et turbaris erga plurima: porro unum est necessarium. Maria optimam partem elegit, quae non auferetur ab ea.”"}],"Offertorium":[{"k":"ref","la":"Ps 44:10"},{"k":"text","la":"Fíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:4-6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5f74a5115cb0ce83":{"t":"Ps 44, 8, Ps 44, 2\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje.","kn":"(Ps. 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti izabravši te od svih dru.garica tvojih, Aleluja, Aleluja (Ps. 44, 2). Iz mog srca Izvire divna pjesma: djela su moja namijenjena kralju! Slava Ocu. Ti ljubiš.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"10586c17b3b45eab":{"t":"<i>Pomolimo se</i>.\nUsliši nas, Bože Spasitelju naš, da kao što se radujemo svetkovini blažene Marte, djevice tvoje, tako uznapredujemo u osjećaju odane pobožnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši nae, Bože, spasitelju naš, kao što se radu-jemo' o svetkovini blažene Praksede, Tvoje djevice, tako da rastemo i u pobožnoj bogoljubnosti, (pp G. n. '","knRef":"Kniewald 1942, str. 648–649 (snimka 325) (OCR)"},"2e242204d5c46dd6":{"t":"2 Kor 10, 17-18, 11, 1-2\nČitanje Poslanice bl. Pavla apostola Korinćamima. Braćo, tko se hvali neka se hvali u Gospodinu. Jer nije prokušan onaj koji se sam hvali, nego koga Bog hvali. O da biste malo podnosili moje bezumlje! Ali ipak podnesite me, jer revnujem za vas Božjom ravnošću. Zaručio sam vas jednom čovjeku Kristu da vas preda nj izvedem kao čistu djevicu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 10, 17-18. 11, 1-2). Braćo! Koji se hvali, neka se hvali u Gospodinu. Jer nije prokušan onaj, koji se sam preporučuje, nego koga preporučuje Bog. O da biste ipodnesld nešto malo moje ludosti! Ali ipak r po'dnesite me, jer revnujem za vas Božjim žarom. Zaručio sam vas jednomu mužu, da vas privedem Kristu kao čistu djevicu.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"c025d479900eacd4":{"t":"Ps 44, 5\nU svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj. Zbog vjernosti, blagosti i pravednosti divno će te voditi tvoja desnica.\n\nPs 44, 15-16\n<i>Aleluja</i>, <i>aleluja</i>.\nZa njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti. <i>Aleluja</i>.","kn":"(Ps. 44, 5). U veličanstvenoj ljepoti svojoj sretno pođi, pohitaj prama pobjedi i kraljuj! Poradi istine i blagosti i pravde vodit će te divno desnica tvoja. Aleluja.\n\nAleluja-, Aleluja (Pr. 44, 15, 16). Prate je djevice I i vode je kralju u radosti i veselju. Aleluja (Ps. 44, ,","knRef":"Kniewald 1942, str. 832–833 (snimka 417) (OCR)"},"f1946cb607a44f24":{"t":"Lk 10, 38-42\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Isus dođe u neko selo, i primi ga u svoju kuću neka žena imenom Marta. Ona je imala sestru Mariju, koja sjede do Isusovih nogu slušajući njegov govor. Marta nastojeći da ga što bolje posluži, pristupi mu i reče: Gospodine, ti ne mariš što me moja sestra ostavi da sama poslužujem? Molim te, reci joj da mi pomogne. Gospodin joj odgovori: Marta, Marta, brineš se i uznemiruješ za mnogo, a potrebno je samo jedno. Marija je izabrala najbolji dio koji joj se neće oduzeti.","kn":"t Slijedi sv. evanđelje po Luki (10, 38-42). U ono vrijeme uđe Isus u neko selo i primi ga u svoju kuću žena po imenu Marta. Ova je imala sestru Mariju, koja je sjedila do Isusovih nogu i slušala njegove riječi. A Marta, jier je, nastojala da što bolje posluži, pristupi i reče: Gospodine, ti ne mariš, što me moja sestra ostavi samu da poslužujem? Reci joj dakle, da mi pomogne. Gospodin joj odgovori: Marta, Marta, brineš se i uznemiruješ za mnoge stvari, a samo je jedno potrebno. Marija je izabrala najbolji dio, koji se ne će oduzeti od nje.","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"3ef3e3394cd6d09a":{"t":"Ps 44, 10\nKraljevske kćeri dolaze ti ususret, Kraljica stoji uz desnu tvoju ogrnuta presjajnom zlatnom haljinom.","kn":"(Ps. 44, 16). Pratit će te kćeri kraljevske: z desne tvoje sama kraljica, ogrnuta presjajnom zlatnom haljinom.","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"135c5bf58bce477d":{"t":"Pogledaj, Gospodine, na darove svoga naroda, i daj mu osjetiti da mu koristi za spasenje ova žrtvena svečanost koju obavlja s pobožnom odanošću na čast tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"a487c4b958415356":{"t":"Mt 25, 4 i 6\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu.","kn":"(Mt. 25, 4, 6.) Pet je mudrih djevica uzelo ulje u posudama svojim sa svjetiljkama; a o ponoći nasta vika: Evo ide zaručnik, iziđite ususrte Kristu Gospodinu!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"}}});
